<?php require_once 'auth.php';require_admin();header('Content-Type: application/json');$pdo=db();$productId=(int)($_POST['product_id']??0);$name=trim($_POST['name']??'');$details=json_decode($_POST['details']??'{}',true);if(!$pdo||!$productId||$name===''||!is_array($details)){http_response_code(422);echo '{"error":"Dữ liệu không hợp lệ"}';exit;}try{$q=$pdo->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM product_size_options WHERE product_id=?');$q->execute([$productId]);$sort=(int)$q->fetchColumn();$pdo->prepare('INSERT INTO product_size_options(product_id,name,details_json,sort_order) VALUES(?,?,?,?)')->execute([$productId,$name,json_encode($details,JSON_UNESCAPED_UNICODE),$sort]);echo '{"ok":true}';}catch(Throwable $e){http_response_code(422);echo '{"error":"Kích thước đã tồn tại"}';}
